(7067954, 1075223, 96751, '<td valign="top">Hahaha! My comment was going to be "before and after", and then I saw the title!</td>', 'Hahaha! My comment was going to be "before and after", and then I saw the title!', '2013-07-12 02:58:22.000000', NULL, 1),
(7067955, 1075291, 96751, '<td valign="top">Great find, not crazy about the pov</td>', 'Great find, not crazy about the pov', '2013-07-12 02:58:37.000000', NULL, 1),
(7067956, 1075388, 96751, '<td valign="top">With just a little more processing, this would have been a fabulous image</td>', 'With just a little more processing, this would have been a fabulous image', '2013-07-12 02:59:15.000000', NULL, 1),
(7067958, 1074649, 96751, '<td valign="top">Such colorful geometry!</td>', 'Such colorful geometry!', '2013-07-12 02:59:38.000000', NULL, 1),
(7067959, 1075364, 96751, '<td valign="top">I think the barn door is unnecessary! Just the square stones with the window would have been plenty great</td>', 'I think the barn door is unnecessary! Just the square stones with the window would have been plenty great', '2013-07-12 03:00:37.000000', NULL, 1),
(7067960, 1075232, 96751, '<td valign="top">the little tree that could. How sweet!</td>', 'the little tree that could. How sweet!', '2013-07-12 03:01:07.000000', NULL, 1),
(7067961, 1075304, 96751, '<td valign="top">Have we not seen this blue bike before? I like that this is more than just a colorful patch of building. There is a story here, and it may be to the detriment of the image in this challenge. Or perhaps not :-)</td>', 'Have we not seen this blue bike before? I like that this is more than just a colorful patch of building. There is a story here, and it may be to the detriment of the image in this challenge. Or perhaps not :-)', '2013-07-12 03:02:01.000000', NULL, 1),
(7067962, 1075265, 96751, '<td valign="top">Niiiiiiice!! i love the slight pink tinge to the wash</td>', 'Niiiiiiice!! i love the slight pink tinge to the wash', '2013-07-12 03:02:26.000000', NULL, 1),
(7067963, 1075282, 96751, '<td valign="top">Another Mondrian!</td>', 'Another Mondrian!', '2013-07-12 03:02:35.000000', NULL, 1),
(7067964, 1075401, 96751, '<td valign="top">This is a very strong image, Nikki. I might have told you to shift the dark blue/green to a more vibrant shade, but this is so elegant.</td>', 'This is a very strong image, Nikki. I might have told you to shift the dark blue/green to a more vibrant shade, but this is so elegant.', '2013-07-12 03:03:20.000000', NULL, 1),
(7067965, 1075326, 96751, '<td valign="top">Ha! Way to make this challenge your own. Well done</td>', 'Ha! Way to make this challenge your own. Well done', '2013-07-12 03:03:49.000000', NULL, 1),
(7067967, 1075278, 96751, '<td valign="top">Lovely! Wonderful textures on the right wall. This could almost be a flag</td>', 'Lovely! Wonderful textures on the right wall. This could almost be a flag', '2013-07-12 03:04:27.000000', NULL, 1),
(7067968, 1074797, 96751, '<td valign="top">I can''t tell if I like this image or not. It certainly made me stop to look at it!</td>', 'I can''t tell if I like this image or not. It certainly made me stop to look at it!', '2013-07-12 03:05:00.000000', NULL, 1),
(7067969, 1075398, 96751, '<td valign="top">Did you find this or make this????? I LOVE it!!!! Very original. Might be my fave so far</td>', 'Did you find this or make this????? I LOVE it!!!! Very original. Might be my fave so far', '2013-07-12 03:05:32.000000', NULL, 1),
(7067972, 1075151, 96751, '<td valign="top">And serenity!</td>', 'And serenity!', '2013-07-12 03:05:55.000000', NULL, 1),
(7067974, 1075318, 96751, '<td valign="top">This is an insane door!  Great find</td>', 'This is an insane door!  Great find', '2013-07-12 03:06:12.000000', NULL, 1),
(7067975, 1075296, 96751, '<td valign="top">I like the beauty of small things. I think this is what the challenge is all about. I might have added a bit of brightness and contrast to make it pop just a tiny bit more</td>', 'I like the beauty of small things. I think this is what the challenge is all about. I might have added a bit of brightness and contrast to make it pop just a tiny bit more', '2013-07-12 03:06:52.000000', NULL, 1),
(7067977, 1075270, 96751, '<td valign="top">Beautiful. So many layers. So many colors</td>', 'Beautiful. So many layers. So many colors', '2013-07-12 03:07:15.000000', NULL, 1),
(7067979, 1075395, 96751, '<td valign="top">That''s one heck of a yellow</td>', 'That''s one heck of a yellow', '2013-07-12 03:07:34.000000', NULL, 1),
(7067980, 1075346, 96751, '<td valign="top">Even without the chord, this is a terrific, geometric image. With the chord, it''s human. Really nicely balanced</td>', 'Even without the chord, this is a terrific, geometric image. With the chord, it''s human. Really nicely balanced', '2013-07-12 03:08:09.000000', NULL, 1),
(7067981, 1075394, 96751, '<td valign="top">Another very powerful, beautifully balanced image. Quite Zen, actually</td>', 'Another very powerful, beautifully balanced image. Quite Zen, actually', '2013-07-12 03:08:40.000000', NULL, 1),
(7068024, 1075181, 86218, '<td valign="top">Perfect.. This is just stunning. Perfect new happines and who would not have this during an endless summer. 9</td>', 'Perfect.. This is just stunning. Perfect new happines and who would not have this during an endless summer. 9', '2013-07-12 05:19:35.000000', NULL, 1),
(7068025, 1075385, 86218, '<td valign="top">Enjoying this challenge sooooo much. For a simple mind like mine these shots are refreshing. Great take and that shadow line makes this image well composed</td>', 'Enjoying this challenge sooooo much. For a simple mind like mine these shots are refreshing. Great take and that shadow line makes this image well composed', '2013-07-12 05:21:17.000000', NULL, 1),
(7068026, 1074960, 86218, '<td valign="top">So much tension and conflict in such a simple image. What a shot. lovely work</td>', 'So much tension and conflict in such a simple image. What a shot. lovely work', '2013-07-12 05:23:11.000000', NULL, 1),
(7068034, 1075358, 123833, '<td valign="top">I hope that compensates :)</td>', 'I hope that compensates :)', '2013-07-12 06:44:36.000000', NULL, 1),
