(7068390, 1075406, 112828, '<td valign="top">A tighter crop would have been much better.  Too much distraction with all that ground stuff and the light at the top.<br/> <br/>Perhaps just a section of the right hand side of the door with window, frame, and red boards, on a rule of thirds layout would have been stronger.<br/> <br/> <br/>Still, a really nice image!</td>', 'A tighter crop would have been much better.  Too much distraction with all that ground stuff and the light at the top. Perhaps just a section of the right hand side of the door with window, frame, and red boards, on a rule of thirds layout would have been stronger.  Still, a really nice image!', '2013-07-12 16:18:24.000000', NULL, 1),
(7068391, 1075202, 112828, '<td valign="top">Cute!<br/> <br/>Very creative.</td>', 'Cute! Very creative.', '2013-07-12 16:18:42.000000', NULL, 1),
(7068393, 1075253, 112828, '<td valign="top">Mostly I think of Angus as having been drawn to straight line geometric work.<br/> <br/>Still, I don''t think he would have passed this awesome shot up.<br/> <br/>Really nice shot, I especially like how the tarmacadam adds to the image.</td>', 'Mostly I think of Angus as having been drawn to straight line geometric work. Still, I don''t think he would have passed this awesome shot up. Really nice shot, I especially like how the tarmacadam adds to the image.', '2013-07-12 16:20:00.000000', NULL, 1),
(7068394, 1075404, 112828, '<td valign="top">Very well found, and very well shot!</td>', 'Very well found, and very well shot!', '2013-07-12 16:20:15.000000', NULL, 1),
(7068395, 1075374, 112828, '<td valign="top">Love the colors here, although the ground is a little cluttered and distracting.<br/><br/><i>Message edited by author 2013-07-19 01:54:34.</i></td>', 'Love the colors here, although the ground is a little cluttered and distracting.', '2013-07-12 16:20:36.000000', '2013-07-19 02:54:34.000000', 1),
(7068396, 1075232, 112828, '<td valign="top">Nice composition, great texture.</td>', 'Nice composition, great texture.', '2013-07-12 16:20:58.000000', NULL, 1),
(7068397, 1075385, 112828, '<td valign="top">I don''t like the falloff of that shadow at the top.<br/> <br/>The yellow is a little too saturated/blown.<br/> <br/>..<br/> <br/>Still, with all of that being said - it''s a superb image, and is very happy indeed!</td>', 'I don''t like the falloff of that shadow at the top. The yellow is a little too saturated/blown. .. Still, with all of that being said - it''s a superb image, and is very happy indeed!', '2013-07-12 16:21:37.000000', NULL, 1),
(7068398, 1075264, 112828, '<td valign="top">Creative, and wonderful.<br/> <br/>I find the colors and luminosity to be a little muted here though.</td>', 'Creative, and wonderful. I find the colors and luminosity to be a little muted here though.', '2013-07-12 16:22:08.000000', NULL, 1),
(7068400, 1074804, 112828, '<td valign="top">Now that''s a fun image.  Wonderful spot.<br/> <br/>The kid doesn''t look particularly ''happy'' though. ;)</td>', 'Now that''s a fun image.  Wonderful spot. The kid doesn''t look particularly ''happy'' though. ;)', '2013-07-12 16:22:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7068401, 1075182, 112828, '<td valign="top">Nice colors, and good accent.<br/> <br/>Don''t think I like the harsh shadow though.</td>', 'Nice colors, and good accent. Don''t think I like the harsh shadow though.', '2013-07-12 16:23:10.000000', NULL, 1),
(7068402, 1075304, 112828, '<td valign="top">This is extremely pretty, and very well composed.<br/> <br/>The blacks here are totally gray though - really wish they were deeper.</td>', 'This is extremely pretty, and very well composed. The blacks here are totally gray though - really wish they were deeper.', '2013-07-12 16:23:56.000000', NULL, 1),
(7068403, 1075388, 112828, '<td valign="top">Too soft, but otherwise this is really a good find, and meets the challenge well.</td>', 'Too soft, but otherwise this is really a good find, and meets the challenge well.', '2013-07-12 16:24:17.000000', NULL, 1),
(7068404, 1075318, 112828, '<td valign="top">Yikes!  That tilt just destroys what is otherwise a superb image.<br/> <br/>Made me a little sad for you honestly - since this is such an otherwise happy image.</td>', 'Yikes!  That tilt just destroys what is otherwise a superb image. Made me a little sad for you honestly - since this is such an otherwise happy image.', '2013-07-12 16:24:56.000000', NULL, 1),
(7068405, 1075183, 112828, '<td valign="top">Wow.   Noise.<br/> <br/>Pretty happy still though.</td>', 'Wow.   Noise. Pretty happy still though.', '2013-07-12 16:25:19.000000', NULL, 1),
(7068406, 1075399, 112828, '<td valign="top">Yes - I love the feel of this one.</td>', 'Yes - I love the feel of this one.', '2013-07-12 16:25:30.000000', NULL, 1),
(7068407, 1075392, 112828, '<td valign="top">ROFL .  This really didn''t meet the challenge well - but I still like it very much.</td>', 'ROFL .  This really didn''t meet the challenge well - but I still like it very much.', '2013-07-12 16:26:13.000000', NULL, 1),
(7068408, 1075324, 112828, '<td valign="top">Nice image.  Although I think it''s not super-well suited to the challenge, generally it has the right feel, and is well shot and processed.</td>', 'Nice image.  Although I think it''s not super-well suited to the challenge, generally it has the right feel, and is well shot and processed.', '2013-07-12 16:26:53.000000', NULL, 1),
(7068409, 1075277, 112828, '<td valign="top">A creative choice!<br/> <br/>Would have scored this higher if you''d cloned out those wires, and had saturated those colors a bit more.</td>', 'A creative choice! Would have scored this higher if you''d cloned out those wires, and had saturated those colors a bit more.', '2013-07-12 16:27:21.000000', NULL, 1),
(7068413, 1075393, 112828, '<td valign="top">The colors are right, and it''s very creative and imaginative.<br/> <br/>With that being said - here''s why I''m giving this a 4.<br/> <br/>The background is a mess, totally should have made that much deeper black on the left.<br/> <br/>The chair is a little soft overall, and is kinda faded in color.<br/> <br/>Of course, then there''s the fact that Angus didn''t shoot chairs, or use a studio.<br/> <br/>*shrug*.  Can''t quite figure out if there''s a story here either.  If I could only find a story this would go to a 5 or 6 at least.</td>', 'The colors are right, and it''s very creative and imaginative. With that being said - here''s why I''m giving this a 4. The background is a mess, totally should have made that much deeper black on the left. The chair is a little soft overall, and is kinda faded in color. Of course, then there''s the fact that Angus didn''t shoot chairs, or use a studio. *shrug*.  Can''t quite figure out if there''s a story here either.  If I could only find a story this would go to a 5 or 6 at least.', '2013-07-12 16:29:35.000000', NULL, 1),
(7068414, 1075076, 112828, '<td valign="top">Processing lets this down a little.</td>', 'Processing lets this down a little.', '2013-07-12 16:29:47.000000', NULL, 1),
(7068415, 1075246, 112828, '<td valign="top">A totally cool image - but I don''t know if it fits the challenge very well.  Can''t quite put this together with his work.</td>', 'A totally cool image - but I don''t know if it fits the challenge very well.  Can''t quite put this together with his work.', '2013-07-12 16:30:18.000000', NULL, 1),
(7068416, 1075164, 112828, '<td valign="top">Cool image.<br/> <br/>DOF is too shallow though, and I''m having a little bit of trouble associating this with the challenge.</td>', 'Cool image. DOF is too shallow though, and I''m having a little bit of trouble associating this with the challenge.', '2013-07-12 16:30:56.000000', NULL, 1),
(7068418, 1075269, 112828, '<td valign="top">Wow!  Really neat image - very powerful, and with a perfect crop.  Bumping a point.<br/> <br/>Not quite as ''happy'' as I would like, but still superb.</td>', 'Wow!  Really neat image - very powerful, and with a perfect crop.  Bumping a point. Not quite as ''happy'' as I would like, but still superb.', '2013-07-12 16:31:55.000000', NULL, 1),
(7068419, 1074721, 112828, '<td valign="top">This would have been three points higher for me if you had only fixed that horrible perspective distortion.</td>', 'This would have been three points higher for me if you had only fixed that horrible perspective distortion.', '2013-07-12 16:32:21.000000', NULL, 1),
(7068420, 1075254, 112828, '<td valign="top">Great feel to this image, lovely in fact.<br/> <br/>I''m afraid that it''s nearly entirely DNMC though.  I''ll give you a 5 since it''s just so darn nice otherwise.</td>', 'Great feel to this image, lovely in fact. I''m afraid that it''s nearly entirely DNMC though.  I''ll give you a 5 since it''s just so darn nice otherwise.', '2013-07-12 16:32:59.000000', NULL, 1),
(7068421, 1075173, 112828, '<td valign="top">Great crop on this.  A little sharper would have been nice.</td>', 'Great crop on this.  A little sharper would have been nice.', '2013-07-12 16:33:24.000000', NULL, 1),
(7068425, 1075071, 112828, '<td valign="top">Happy as can be!</td>', 'Happy as can be!', '2013-07-12 16:34:44.000000', NULL, 1),
(7068427, 1074701, 112828, '<td valign="top">Interesting.  I don''t find it to have the right ''feel'' of happiness, but it''s a well found image, and I think generally meets the challenge well.</td>', 'Interesting.  I don''t find it to have the right ''feel'' of happiness, but it''s a well found image, and I think generally meets the challenge well.', '2013-07-12 16:35:34.000000', NULL, 1),
(7068430, 1075302, 112828, '<td valign="top">Nice landscape.<br/> <br/>I can only assume this was an honest mistake and was entered into the wrong challenge by accident.  Clearly you were looking for the freestudy. ;)<br/> <br/>Seriously though - there is a mild resemblance to the geometric feel of Angus''s work, and this of course evokes that stupidly expensive picture of the Rhine river - so bonus points are being awarded on that basis.</td>', 'Nice landscape. I can only assume this was an honest mistake and was entered into the wrong challenge by accident.  Clearly you were looking for the freestudy. ;) Seriously though - there is a mild resemblance to the geometric feel of Angus''s work, and this of course evokes that stupidly expensive picture of the Rhine river - so bonus points are being awarded on that basis.', '2013-07-12 16:37:00.000000', NULL, 1),
(7068432, 1075401, 112828, '<td valign="top">Interesting find.  Too soft overall, and (unusually for this challenge) maybe a little too tightly cropped.</td>', 'Interesting find.  Too soft overall, and (unusually for this challenge) maybe a little too tightly cropped.', '2013-07-12 16:37:30.000000', NULL, 1),
(7068433, 1075294, 112828, '<td valign="top">Geometric feel here is wonderful.<br/> <br/>Processing feels more like Kodachrome than whatever Angus was using.<br/> <br/>I can''t say I''m going to vote this high - but it''s an image you should be very proud of none-the-less.</td>', 'Geometric feel here is wonderful. Processing feels more like Kodachrome than whatever Angus was using. I can''t say I''m going to vote this high - but it''s an image you should be very proud of none-the-less.', '2013-07-12 16:38:39.000000', NULL, 1),
(7068435, 1074744, 112828, '<td valign="top">This is a mess, both literally and compositionally.<br/> <br/>It does generally meet the challenge, but I think it missed the bigger picture with regards to the deeper meaning of Angus''s work.</td>', 'This is a mess, both literally and compositionally. It does generally meet the challenge, but I think it missed the bigger picture with regards to the deeper meaning of Angus''s work.', '2013-07-12 16:39:46.000000', NULL, 1),
(7068436, 1075361, 112828, '<td valign="top">Pretty kitty!<br/> <br/>DNMC. Bonus points because I like cats.</td>', 'Pretty kitty! DNMC. Bonus points because I like cats.', '2013-07-12 16:40:09.000000', NULL, 1),
(7068440, 1075285, 112828, '<td valign="top">Hmm.<br/> <br/>Ok, so the sheets are totally reminiscent of his work.. The cat is a highly distracting nuisance. (in real life too I''m sure...)<br/> <br/>I like cat pics too much to really punish you, but this is pretty much a DNMC other than the sheets.</td>', 'Hmm. Ok, so the sheets are totally reminiscent of his work.. The cat is a highly distracting nuisance. (in real life too I''m sure...) I like cat pics too much to really punish you, but this is pretty much a DNMC other than the sheets.', '2013-07-12 16:41:32.000000', NULL, 1),
(7068441, 1074965, 112828, '<td valign="top">Interesting take on this - but it would have been stronger without the ground.<br/> <br/>Processing here is also decidedly blotchy.</td>', 'Interesting take on this - but it would have been stronger without the ground. Processing here is also decidedly blotchy.', '2013-07-12 16:42:06.000000', NULL, 1),
(7068444, 1075274, 112828, '<td valign="top">Lovely ribbons.  I''m afraid that this shot won''t earn you another though.</td>', 'Lovely ribbons.  I''m afraid that this shot won''t earn you another though.', '2013-07-12 16:42:39.000000', NULL, 1),
(7068489, 1074815, 23484, '<td valign="top">I like the really busy look.</td>', 'I like the really busy look.', '2013-07-12 17:53:05.000000', NULL, 1),
(7068490, 1075405, 23484, '<td valign="top">Simple yet very nice.</td>', 'Simple yet very nice.', '2013-07-12 17:53:31.000000', NULL, 1),
(7068629, 1074649, 30490, '<td valign="top">Crisp clean colors w/ texture, really spot on for this challenge!</td>', 'Crisp clean colors w/ texture, really spot on for this challenge!', '2013-07-12 20:41:04.000000', NULL, 1),
(7068630, 1074885, 30490, '<td valign="top">Love the colors and the texture!</td>', 'Love the colors and the texture!', '2013-07-12 20:41:22.000000', NULL, 1),
(7068631, 1075182, 30490, '<td valign="top">Love the color, and the contrast plus the play with light and shadow!</td>', 'Love the color, and the contrast plus the play with light and shadow!', '2013-07-12 20:42:18.000000', NULL, 1),
(7068632, 1075151, 30490, '<td valign="top">Really busy, but in a good way. I love the colors and the texture.</td>', 'Really busy, but in a good way. I love the colors and the texture.', '2013-07-12 20:42:50.000000', NULL, 1),
(7068634, 1075181, 30490, '<td valign="top">Crisp, clean, sharp and great colors.  Great image for this challenge!</td>', 'Crisp, clean, sharp and great colors.  Great image for this challenge!', '2013-07-12 20:44:19.000000', NULL, 1),
(7068635, 1075302, 30490, '<td valign="top">HuH? Did we enter the same challenge? You know the one where we were supposed to pay tribute to Angus MacDonald?  I just don''t see how this one is connected to the challenge.  Nice clouds.  Better luck next time.</td>', 'HuH? Did we enter the same challenge? You know the one where we were supposed to pay tribute to Angus MacDonald?  I just don''t see how this one is connected to the challenge.  Nice clouds.  Better luck next time.', '2013-07-12 20:46:33.000000', NULL, 1),
(7068637, 1075392, 30490, '<td valign="top">Yes you did, and it didn''t work for me.  I prefer the images that at least had some connection to the challenge...</td>', 'Yes you did, and it didn''t work for me.  I prefer the images that at least had some connection to the challenge...', '2013-07-12 20:47:27.000000', NULL, 1),
(7068638, 1075361, 30490, '<td valign="top">Nice image of a cat, which certainly makes me "happy" but this image just didn''t connect to the topic of the challenge at all.  You get a "4" from me for it being a decent cat photo....</td>', 'Nice image of a cat, which certainly makes me "happy" but this image just didn''t connect to the topic of the challenge at all.  You get a "4" from me for it being a decent cat photo....', '2013-07-12 20:48:43.000000', NULL, 1),
(7068641, 1075076, 30490, '<td valign="top">OK, you got a bit of the cheery color, and lots of texture, but it is just too far out of the challenge box for my taste. 4</td>', 'OK, you got a bit of the cheery color, and lots of texture, but it is just too far out of the challenge box for my taste. 4', '2013-07-12 20:50:04.000000', NULL, 1),
(7068642, 1075316, 30490, '<td valign="top">Great idea and spot on for the challenge, but the white paint area seems blown out to me.  Maybe if you had cropped it differently I would have rated this image higher.</td>', 'Great idea and spot on for the challenge, but the white paint area seems blown out to me.  Maybe if you had cropped it differently I would have rated this image higher.', '2013-07-12 20:51:28.000000', NULL, 1),
(7068644, 1075202, 30490, '<td valign="top">Love the color, the texture and the gecko. I don''t care for the tile with the verse. It is just my personal opinion.  You got a 5 from me for having a technically good photo, it just didn''t capture my attention or imagination.</td>', 'Love the color, the texture and the gecko. I don''t care for the tile with the verse. It is just my personal opinion.  You got a 5 from me for having a technically good photo, it just didn''t capture my attention or imagination.', '2013-07-12 20:53:29.000000', NULL, 1),
(7068646, 1075002, 30490, '<td valign="top">Great texture, interesting person, but lacking in color.  This image just didn''t capture my imagination the same way others in this challenge did.  5 for a good effort.</td>', 'Great texture, interesting person, but lacking in color.  This image just didn''t capture my imagination the same way others in this challenge did.  5 for a good effort.', '2013-07-12 20:54:38.000000', NULL, 1),
(7068647, 1075393, 30490, '<td valign="top">A very "out of the box" entry for this challenge.  I like the colors, and the texture of the wooden chair, but it looks like you have a DOF issue and the chair back is OOF.  This one just didn''t work that well for me.  a "5" for effort</td>', 'A very "out of the box" entry for this challenge.  I like the colors, and the texture of the wooden chair, but it looks like you have a DOF issue and the chair back is OOF.  This one just didn''t work that well for me.  a "5" for effort', '2013-07-12 20:55:55.000000', NULL, 1),
(7068648, 1075398, 30490, '<td valign="top">An out of the box entry for this challenge.  I think the color is just too dark to evoke the MacDonald images.  I gave you a 5 for a good effort.</td>', 'An out of the box entry for this challenge.  I think the color is just too dark to evoke the MacDonald images.  I gave you a 5 for a good effort.', '2013-07-12 20:56:56.000000', NULL, 1),
(7068649, 1075269, 30490, '<td valign="top">Too busy of an image for my taste.  It is a good overall image, just didn''t evoke MacDonald to me.  5 for good effort!</td>', 'Too busy of an image for my taste.  It is a good overall image, just didn''t evoke MacDonald to me.  5 for good effort!', '2013-07-12 20:58:08.000000', NULL, 1),
(7068650, 1075358, 30490, '<td valign="top">Gritty with texture, it is just missing the warmth of the colors.  5 for effort.</td>', 'Gritty with texture, it is just missing the warmth of the colors.  5 for effort.', '2013-07-12 20:58:44.000000', NULL, 1),
(7068651, 1074701, 30490, '<td valign="top">So many textures and colors.  I think you were on the right path, but just didn''t quite make it.  Maybe a change of crop would have improved this image.  a 5 for effort from me.</td>', 'So many textures and colors.  I think you were on the right path, but just didn''t quite make it.  Maybe a change of crop would have improved this image.  a 5 for effort from me.', '2013-07-12 20:59:45.000000', NULL, 1),
(7068652, 1075275, 30490, '<td valign="top">A great sign that would have been fabulous with a different crop.  If you had zoomed in on the sign and lost the rest of the background it would have been a much better image for this challenge.  a 5 for effort though!</td>', 'A great sign that would have been fabulous with a different crop.  If you had zoomed in on the sign and lost the rest of the background it would have been a much better image for this challenge.  a 5 for effort though!', '2013-07-12 21:01:00.000000', NULL, 1),
(7068654, 1075326, 30490, '<td valign="top">You have color, and texture so why doesn''t this work for me?  I think if you had cropped out the shower rail and made both the curtain and rug really crisp that this would have been an image that worked better for me.  A 5 for effort.</td>', 'You have color, and texture so why doesn''t this work for me?  I think if you had cropped out the shower rail and made both the curtain and rug really crisp that this would have been an image that worked better for me.  A 5 for effort.', '2013-07-12 21:02:33.000000', NULL, 1),
(7068657, 1075324, 30490, '<td valign="top">Too busy for me.  The MacDonald images were simple and clean.  The contrast between the two types of bricks would have been a stronger entry in my opinion.  a 5 for effort from me</td>', 'Too busy for me.  The MacDonald images were simple and clean.  The contrast between the two types of bricks would have been a stronger entry in my opinion.  a 5 for effort from me', '2013-07-12 21:03:39.000000', NULL, 1),
(7068658, 1075274, 30490, '<td valign="top">An out of the box entry for this challenge.  Image is just a bit too dark for my taste.  I gave you a 5 for effort.</td>', 'An out of the box entry for this challenge.  Image is just a bit too dark for my taste.  I gave you a 5 for effort.', '2013-07-12 21:04:23.000000', NULL, 1),
(7068659, 1074965, 30490, '<td valign="top">Good effort, I think I would have liked it better with the ad cropped out of the image and more focused on the contrast of the tire to the bus body.  Your colors are great though, so a 5 for effort from me.</td>', 'Good effort, I think I would have liked it better with the ad cropped out of the image and more focused on the contrast of the tire to the bus body.  Your colors are great though, so a 5 for effort from me.', '2013-07-12 21:05:37.000000', NULL, 1),
(7068660, 1074734, 30490, '<td valign="top">Great texture.  Colors are okay, but what happened to the white?  It looks completely blown out to me... 5 for effort from me</td>', 'Great texture.  Colors are okay, but what happened to the white?  It looks completely blown out to me... 5 for effort from me', '2013-07-12 21:06:23.000000', NULL, 1),
(7068662, 1075294, 30490, '<td valign="top">An out of the box entry for this challenge.  I like the texture formed by the glass, but the color seems a bit muted to me if you want to pay tribute to the New Happiness images.  a 5 for effort from me</td>', 'An out of the box entry for this challenge.  I like the texture formed by the glass, but the color seems a bit muted to me if you want to pay tribute to the New Happiness images.  a 5 for effort from me', '2013-07-12 21:07:36.000000', NULL, 1),
(7068663, 1075285, 30490, '<td valign="top">good colors, but your image has some focus issues and the white fur is kind of blown out.  A 5 for effort from me</td>', 'good colors, but your image has some focus issues and the white fur is kind of blown out.  A 5 for effort from me', '2013-07-12 21:08:22.000000', NULL, 1),
(7068667, 1075004, 112828, '<td valign="top">Love this one Rob - I think it''s among the very best in this challenge.<br/> <br/>Really like how that red portlight (I thought it was a porthole) evokes the red round signs in Angus''s work.</td>', 'Love this one Rob - I think it''s among the very best in this challenge. Really like how that red portlight (I thought it was a porthole) evokes the red round signs in Angus''s work.', '2013-07-12 21:12:54.000000', NULL, 1),
(7068687, 1075392, 100975, '<td valign="top">I don''t see the connection between your image and the challenge.  It is definitely a strange image.  Is this from the side of a building?</td>', 'I don''t see the connection between your image and the challenge.  It is definitely a strange image.  Is this from the side of a building?', '2013-07-12 22:32:22.000000', NULL, 1),
(7068688, 1075302, 100975, '<td valign="top">Sorry, I do not see the connection between your photo and the challenge.  This would have been a nice cloud challenge though.</td>', 'Sorry, I do not see the connection between your photo and the challenge.  This would have been a nice cloud challenge though.', '2013-07-12 22:33:27.000000', NULL, 1),
(7068689, 1074965, 100975, '<td valign="top">If there would have been a way to find a different view of this truck, I would have scored it higher.  I really don''t care for the image on the truck.</td>', 'If there would have been a way to find a different view of this truck, I would have scored it higher.  I really don''t care for the image on the truck.', '2013-07-12 22:35:15.000000', NULL, 1),
(7068694, 1075277, 100975, '<td valign="top">Nice play on the words and I like the color.  Composition wise, I think I would have liked it more had there been the full circle in the middle (if possible) and maybe rotate more so that the corners matched a little more (if possible).</td>', 'Nice play on the words and I like the color.  Composition wise, I think I would have liked it more had there been the full circle in the middle (if possible) and maybe rotate more so that the corners matched a little more (if possible).', '2013-07-12 22:38:16.000000', NULL, 1),
(7068699, 1075300, 100975, '<td valign="top">I like how the tree mimics the vertical lines of the pipes in the inspiration photos.  Very light and airy feel...calming.</td>', 'I like how the tree mimics the vertical lines of the pipes in the inspiration photos.  Very light and airy feel...calming.', '2013-07-12 22:43:58.000000', NULL, 1),
(7068701, 1075182, 100975, '<td valign="top">I like the color in this and I also like the diagonal line of light.  One of the better images.</td>', 'I like the color in this and I also like the diagonal line of light.  One of the better images.', '2013-07-12 22:45:43.000000', NULL, 1),
(7068706, 1075346, 100975, '<td valign="top">My daughter rated this the highest out of all of the images.  I like it as well.</td>', 'My daughter rated this the highest out of all of the images.  I like it as well.', '2013-07-12 22:50:34.000000', NULL, 1),
