(7069689, 1075002, 25355, '<td valign="top">You were right to include the man.</td>', 'You were right to include the man.', '2013-07-14 04:14:56.000000', NULL, 1),
(7069690, 1075227, 25355, '<td valign="top">This has a kind of old world charm (well, not too Old World...). It needs a bit more brightness, though; but I can understand it depends on what time of day you can be there.</td>', 'This has a kind of old world charm (well, not too Old World...). It needs a bit more brightness, though; but I can understand it depends on what time of day you can be there.', '2013-07-14 04:17:51.000000', NULL, 1),
(7069691, 1075037, 25355, '<td valign="top">Great colours; fits well with the theme. Gus would have approved.</td>', 'Great colours; fits well with the theme. Gus would have approved.', '2013-07-14 04:20:27.000000', NULL, 1),
(7069692, 1075274, 25355, '<td valign="top">Used to be ... then it''s not new happiness but old happiness. ;-Þ</td>', 'Used to be ... then it''s not new happiness but old happiness. ;-Þ', '2013-07-14 04:21:30.000000', NULL, 1),
(7069693, 1075270, 25355, '<td valign="top">Mysterious. I''m still not sure what goes on behind the green door. ;-Þ</td>', 'Mysterious. I''m still not sure what goes on behind the green door. ;-Þ', '2013-07-14 04:30:06.000000', NULL, 1),
(7069694, 1075298, 25355, '<td valign="top">I like how you''ve used all the colours of the rainbow except for six of them. I would have preferred a straight on view rather than looking up, but I guess you didn''t have a step ladder available at the time.</td>', 'I like how you''ve used all the colours of the rainbow except for six of them. I would have preferred a straight on view rather than looking up, but I guess you didn''t have a step ladder available at the time.', '2013-07-14 04:32:27.000000', NULL, 1),
(7069695, 1075182, 25355, '<td valign="top">I''ve never seen a circular padlock like that before. Good effort.</td>', 'I''ve never seen a circular padlock like that before. Good effort.', '2013-07-14 04:34:42.000000', NULL, 1),
(7069696, 1075071, 25355, '<td valign="top">Very bright and colourful.</td>', 'Very bright and colourful.', '2013-07-14 04:35:42.000000', NULL, 1),
(7069697, 1075291, 25355, '<td valign="top">Is that an air conditioning unit? We could have done without that in the composition</td>', 'Is that an air conditioning unit? We could have done without that in the composition', '2013-07-14 04:37:01.000000', NULL, 1),
(7069700, 1075285, 25355, '<td valign="top">You''ve got the stripy colours, but Gus''s theme was mostly about the quirkiness of painted buildings</td>', 'You''ve got the stripy colours, but Gus''s theme was mostly about the quirkiness of painted buildings', '2013-07-14 04:41:09.000000', NULL, 1),
(7069701, 1075398, 25355, '<td valign="top">Is this a child''s maze project? Acrylic paints are wonderful, aren''t they? Good job.</td>', 'Is this a child''s maze project? Acrylic paints are wonderful, aren''t they? Good job.', '2013-07-14 04:42:35.000000', NULL, 1),
(7069702, 1074744, 25355, '<td valign="top">I think this is a case where a clean-up was in order. The spider webs and grass detract a bit from the image.</td>', 'I think this is a case where a clean-up was in order. The spider webs and grass detract a bit from the image.', '2013-07-14 04:44:19.000000', NULL, 1),
(7069703, 1075404, 25355, '<td valign="top">Which begs the question - what happens if you turn the key to the left? The booby trap is set off?</td>', 'Which begs the question - what happens if you turn the key to the left? The booby trap is set off?', '2013-07-14 04:45:59.000000', NULL, 1),
(7069704, 1075401, 25355, '<td valign="top">Good juan, José.</td>', 'Good juan, José.', '2013-07-14 04:48:48.000000', NULL, 1),
(7069707, 1075275, 25355, '<td valign="top">Just the sign would have been fine.</td>', 'Just the sign would have been fine.', '2013-07-14 04:59:44.000000', NULL, 1),
(7069708, 1074870, 25355, '<td valign="top">I''ve never seen such crooked brickwork, except perhaps in Russia.</td>', 'I''ve never seen such crooked brickwork, except perhaps in Russia.', '2013-07-14 05:00:45.000000', NULL, 1),
(7069710, 1075302, 25355, '<td valign="top">Gus''s "New Happiness" folio was mostly about the quirky colours he found on buildings in Malé in the Maldives, with not a cloud in sight.</td>', 'Gus''s "New Happiness" folio was mostly about the quirky colours he found on buildings in Malé in the Maldives, with not a cloud in sight.', '2013-07-14 05:03:40.000000', NULL, 1),
(7069711, 1075300, 114285, '<td valign="top">sweet comp, love the blue 7</td>', 'sweet comp, love the blue 7', '2013-07-14 05:33:14.000000', NULL, 1),
(7069712, 1075265, 114285, '<td valign="top">cool shadow, sad clothing! 7</td>', 'cool shadow, sad clothing! 7', '2013-07-14 05:35:06.000000', NULL, 1),
(7069713, 1075181, 114285, '<td valign="top">Awesome!</td>', 'Awesome!', '2013-07-14 05:35:41.000000', NULL, 1),
(7069715, 1075304, 114285, '<td valign="top">I wanted to do something like this, well done!! Great tones in the yellow and blue.</td>', 'I wanted to do something like this, well done!! Great tones in the yellow and blue.', '2013-07-14 05:38:01.000000', NULL, 1),
(7069716, 1075406, 114285, '<td valign="top">great door!</td>', 'great door!', '2013-07-14 05:38:39.000000', NULL, 1),
(7069718, 1074885, 114285, '<td valign="top">Great comp and lime green color, top 10.</td>', 'Great comp and lime green color, top 10.', '2013-07-14 05:39:35.000000', NULL, 1),
(7069719, 1075232, 114285, '<td valign="top">I really like this one, not sure if it''s an Angus shot, but still very much in the theme i guess</td>', 'I really like this one, not sure if it''s an Angus shot, but still very much in the theme i guess', '2013-07-14 05:40:27.000000', NULL, 1),
(7069720, 1075071, 114285, '<td valign="top">cool</td>', 'cool', '2013-07-14 05:40:45.000000', NULL, 1),
(7069765, 1075326, 25355, '<td valign="top">I wouldn''t have included the curtain rings, shooting a bit lower. (At first I thought it was a sheepskin rug, but of course it''s a towel. isn''t it?)</td>', 'I wouldn''t have included the curtain rings, shooting a bit lower. (At first I thought it was a sheepskin rug, but of course it''s a towel. isn''t it?)', '2013-07-14 10:31:25.000000', NULL, 1),
(7069766, 1074960, 25355, '<td valign="top">You should be a flag designer for some fledgling country. ;-Þ</td>', 'You should be a flag designer for some fledgling country. ;-Þ', '2013-07-14 10:32:40.000000', NULL, 1),
(7069768, 1075151, 25355, '<td valign="top">I''m quite taken by this image.</td>', 'I''m quite taken by this image.', '2013-07-14 10:33:35.000000', NULL, 1),
(7069769, 1075318, 25355, '<td valign="top">Wow. I''d love to see the whole wall. <br/>Would you eat candy coloured like this?</td>', 'Wow. I''d love to see the whole wall. Would you eat candy coloured like this?', '2013-07-14 10:37:57.000000', NULL, 1),
(7069827, 1075394, 68503, '<td valign="top">Im not sure the vibrance or correct textures are there to mimic his style but still a good attempt.</td>', 'Im not sure the vibrance or correct textures are there to mimic his style but still a good attempt.', '2013-07-14 13:00:58.000000', NULL, 1),
(7069828, 1075270, 68503, '<td valign="top">this is a great texture piece but I think its too flat to convey his style. Cool shot though</td>', 'this is a great texture piece but I think its too flat to convey his style. Cool shot though', '2013-07-14 13:01:46.000000', NULL, 1),
(7069829, 1075275, 68503, '<td valign="top">I think the arrows are a great find along with the colors but I think a closer crop on just them would have scored better.</td>', 'I think the arrows are a great find along with the colors but I think a closer crop on just them would have scored better.', '2013-07-14 13:03:08.000000', NULL, 1),
(7069830, 1075002, 68503, '<td valign="top">Not enough color or vibrance to emulate his style, even though the human element is entertaining.</td>', 'Not enough color or vibrance to emulate his style, even though the human element is entertaining.', '2013-07-14 13:04:14.000000', NULL, 1),
(7069832, 1075324, 68503, '<td valign="top">I like the separation of the two walls but the materials are not in his style and the colors are not vibrant enough, and I dont remember seeing any flowers in his port but I could be wrong. Still a nice take on the challenge.</td>', 'I like the separation of the two walls but the materials are not in his style and the colors are not vibrant enough, and I dont remember seeing any flowers in his port but I could be wrong. Still a nice take on the challenge.', '2013-07-14 13:05:49.000000', NULL, 1),
(7069857, 1075278, 23484, '<td valign="top">Nice verticals. I like the difference in colors in some of these buildings.</td>', 'Nice verticals. I like the difference in colors in some of these buildings.', '2013-07-14 13:32:21.000000', NULL, 1),
(7069859, 1075231, 23484, '<td valign="top">Perfect composition.</td>', 'Perfect composition.', '2013-07-14 13:33:15.000000', NULL, 1),
(7069862, 1075151, 23484, '<td valign="top">I like the way all those different cut marks give it texture.</td>', 'I like the way all those different cut marks give it texture.', '2013-07-14 13:33:59.000000', NULL, 1),
(7069864, 1075398, 23484, '<td valign="top">A homemade maze. Cool.</td>', 'A homemade maze. Cool.', '2013-07-14 13:34:31.000000', NULL, 1),
(7070005, 1075254, 30490, '<td valign="top">I like this image, but it seems a big stretch from the images in New Happiness.  That being said, I like the texture and the reflection and I can see a wispy link to MacDonald''s images.  A nice image and good effort gets a 6 from me.</td>', 'I like this image, but it seems a big stretch from the images in New Happiness.  That being said, I like the texture and the reflection and I can see a wispy link to MacDonald''s images.  A nice image and good effort gets a 6 from me.', '2013-07-14 15:57:54.000000', NULL, 1),
(7070008, 1075227, 30490, '<td valign="top">Nice image, love the colors and texture.  I think I would have cropped the door handle out of the image, it is a bit distracting.</td>', 'Nice image, love the colors and texture.  I think I would have cropped the door handle out of the image, it is a bit distracting.', '2013-07-14 15:59:04.000000', NULL, 1),
(7070011, 1075394, 30490, '<td valign="top">I like this a lot.  The contrast between the "newish" red dot and the old chipped wooden paint is really interesting.</td>', 'I like this a lot.  The contrast between the "newish" red dot and the old chipped wooden paint is really interesting.', '2013-07-14 16:00:00.000000', NULL, 1),
(7070014, 1075196, 30490, '<td valign="top">Hmm you could have entered this in the shadow and light challenge too!  I like the lines formed by the shadows and the bright color.  A nice image for this challenge</td>', 'Hmm you could have entered this in the shadow and light challenge too!  I like the lines formed by the shadows and the bright color.  A nice image for this challenge', '2013-07-14 16:00:56.000000', NULL, 1),
(7070016, 1075173, 30490, '<td valign="top">You got color and texture and a gritty urban feel.  Spot on for this challenge!</td>', 'You got color and texture and a gritty urban feel.  Spot on for this challenge!', '2013-07-14 16:01:29.000000', NULL, 1),
(7070019, 1074782, 30490, '<td valign="top">A creative take on this challenge.  I''m impressed that the white window frame didn''t get "blown" out and that you can still see abundant texture.</td>', 'A creative take on this challenge.  I''m impressed that the white window frame didn''t get "blown" out and that you can still see abundant texture.', '2013-07-14 16:02:32.000000', NULL, 1),
(7070021, 1075264, 30490, '<td valign="top">I like this one.  Nice bright colors and musical notes for interest.  Good capture and entry for this challenge</td>', 'I like this one.  Nice bright colors and musical notes for interest.  Good capture and entry for this challenge', '2013-07-14 16:03:15.000000', NULL, 1),
(7070023, 1075380, 30490, '<td valign="top">I like this image, gritty and full of texture.  It makes me wonder about the pink birds though.  Are they graffiti?  Advertising?  Inquiring minds like to fill in the details, and that is half the fun of looking at photos,</td>', 'I like this image, gritty and full of texture.  It makes me wonder about the pink birds though.  Are they graffiti?  Advertising?  Inquiring minds like to fill in the details, and that is half the fun of looking at photos,', '2013-07-14 16:04:46.000000', NULL, 1),
(7070025, 1075399, 30490, '<td valign="top">Wow it wasn''t until I came back to comment that I realized all the different "t"s in this image!  Nicely done, great texture.</td>', 'Wow it wasn''t until I came back to comment that I realized all the different "t"s in this image!  Nicely done, great texture.', '2013-07-14 16:05:39.000000', NULL, 1),
(7070026, 1075346, 30490, '<td valign="top">I like the idea of this image, but it seems a bit blurry to me especially in the yellow and green of the door.  It is spot on for the challenge and you got a 6 from me.</td>', 'I like the idea of this image, but it seems a bit blurry to me especially in the yellow and green of the door.  It is spot on for the challenge and you got a 6 from me.', '2013-07-14 16:06:44.000000', NULL, 1),
(7070029, 1075404, 30490, '<td valign="top">I love the texture of the blue paint and the contrast with the door key.  I think I would have removed the post it note for your image and replaced it when you were done. It is just distracting w/in the image.</td>', 'I love the texture of the blue paint and the contrast with the door key.  I think I would have removed the post it note for your image and replaced it when you were done. It is just distracting w/in the image.', '2013-07-14 16:07:51.000000', NULL, 1),
(7070031, 1075183, 30490, '<td valign="top">Great image, just a little fuzzy for my taste. Gave you a 6 for a very strong challenge entry</td>', 'Great image, just a little fuzzy for my taste. Gave you a 6 for a very strong challenge entry', '2013-07-14 16:08:39.000000', NULL, 1),
(7070033, 1075230, 30490, '<td valign="top">Spot on for this challenge!  Love the colors and the texture.</td>', 'Spot on for this challenge!  Love the colors and the texture.', '2013-07-14 16:09:04.000000', NULL, 1),
(7070034, 1074723, 30490, '<td valign="top">I like this, it is a different perspective on the challenge.  I keep wondering what we are looking at up close.... a basketball? Sport equipment of some sort?  Half the fun in viewing is the guessing about what it is....</td>', 'I like this, it is a different perspective on the challenge.  I keep wondering what we are looking at up close.... a basketball? Sport equipment of some sort?  Half the fun in viewing is the guessing about what it is....', '2013-07-14 16:10:22.000000', NULL, 1),
(7070035, 1075231, 30490, '<td valign="top">Nice image of the bike and the building.  Spot on for the challenge!</td>', 'Nice image of the bike and the building.  Spot on for the challenge!', '2013-07-14 16:10:46.000000', NULL, 1),
(7070037, 1075265, 30490, '<td valign="top">More play with light and shadow, plus fits with the challenge.  Great image overall!  You got a 7 from me</td>', 'More play with light and shadow, plus fits with the challenge.  Great image overall!  You got a 7 from me', '2013-07-14 16:11:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7070039, 1075004, 30490, '<td valign="top">I like this one.  The white is a bit blown out for my taste, but great image overall</td>', 'I like this one.  The white is a bit blown out for my taste, but great image overall', '2013-07-14 16:11:53.000000', NULL, 1),
(7070040, 1075270, 30490, '<td valign="top">Gritty and messy, but I love it.  It is a few steps from the New Happiness images but I see the connection and appreciate your out of the box view.</td>', 'Gritty and messy, but I love it.  It is a few steps from the New Happiness images but I see the connection and appreciate your out of the box view.', '2013-07-14 16:12:40.000000', NULL, 1),
(7070041, 1075296, 30490, '<td valign="top">I like the texture, colors and the hook!  A unique take on this challenge!</td>', 'I like the texture, colors and the hook!  A unique take on this challenge!', '2013-07-14 16:13:15.000000', NULL, 1),
(7070042, 1075405, 30490, '<td valign="top">Lots of color, and some texture.  A good image, I wonder if a different crop might have made it a stronger entry?  A 6 from me</td>', 'Lots of color, and some texture.  A good image, I wonder if a different crop might have made it a stronger entry?  A 6 from me', '2013-07-14 16:13:58.000000', NULL, 1),
(7070044, 1075071, 30490, '<td valign="top">Lots of color, and character in this image.  Spot on for the challenge too!</td>', 'Lots of color, and character in this image.  Spot on for the challenge too!', '2013-07-14 16:14:41.000000', NULL, 1),
(7070045, 1075277, 30490, '<td valign="top">Is this a hot air balloon?  Colors seem a bit muted to me, maybe they could be punched up with post-processing?  Still a good effort you got a 6 from me</td>', 'Is this a hot air balloon?  Colors seem a bit muted to me, maybe they could be punched up with post-processing?  Still a good effort you got a 6 from me', '2013-07-14 16:15:29.000000', NULL, 1),
(7070046, 1075401, 30490, '<td valign="top">I like this, urban, and gritty with the depth of texture and color!</td>', 'I like this, urban, and gritty with the depth of texture and color!', '2013-07-14 16:15:53.000000', NULL, 1),
(7070047, 1074879, 30490, '<td valign="top">A very nice image in the New Happiness style!  Great job 6 from me</td>', 'A very nice image in the New Happiness style!  Great job 6 from me', '2013-07-14 16:16:27.000000', NULL, 1),
(7070048, 1075232, 30490, '<td valign="top">A great image in the "style" of New Happiness.  I love the texture in the wall.</td>', 'A great image in the "style" of New Happiness.  I love the texture in the wall.', '2013-07-14 16:17:10.000000', NULL, 1),
(7070049, 1075246, 30490, '<td valign="top">Such an odd collection of items.  This image is a bit out of the box and busy for the New Happiness style, but I still like the quality of the image and it has the urban gritty feel that was underlying MacDonald''s images.</td>', 'Such an odd collection of items.  This image is a bit out of the box and busy for the New Happiness style, but I still like the quality of the image and it has the urban gritty feel that was underlying MacDonald''s images.', '2013-07-14 16:18:19.000000', NULL, 1),
(7070050, 1075037, 30490, '<td valign="top">Love this and spot on topic for the challenge!</td>', 'Love this and spot on topic for the challenge!', '2013-07-14 16:18:45.000000', NULL, 1),
(7070052, 1074744, 30490, '<td valign="top">And lots of spider webs! (We have that problem in my area too!)  The image is gritty and full of texture, but just doesn''t grab my attention they way some others in the challenge have.  5 from me</td>', 'And lots of spider webs! (We have that problem in my area too!)  The image is gritty and full of texture, but just doesn''t grab my attention they way some others in the challenge have.  5 from me', '2013-07-14 16:19:43.000000', NULL, 1),
(7070053, 1075403, 30490, '<td valign="top">Your person seems a bit out of focus while the upper right corner is crisp and sharp.  overall a good image for this challenge a 5 from me</td>', 'Your person seems a bit out of focus while the upper right corner is crisp and sharp.  overall a good image for this challenge a 5 from me', '2013-07-14 16:20:27.000000', NULL, 1),
(7070054, 1075204, 30490, '<td valign="top">Love all the lines, I just wish they were straighter.  I had problems with straightness of lines in some of my outtakes too.  It is a challenge when you have so many lines.  The image is spot on the challenge topic so a 6 from me</td>', 'Love all the lines, I just wish they were straighter.  I had problems with straightness of lines in some of my outtakes too.  It is a challenge when you have so many lines.  The image is spot on the challenge topic so a 6 from me', '2013-07-14 16:21:42.000000', NULL, 1),
(7070057, 1075164, 30490, '<td valign="top">This was a bit out of the box for this challenge in my opinion.  But, I like the image and find it very curious.  My mind wants to know what exactly I am looking at.... so you get a 6 from me!</td>', 'This was a bit out of the box for this challenge in my opinion.  But, I like the image and find it very curious.  My mind wants to know what exactly I am looking at.... so you get a 6 from me!', '2013-07-14 16:22:34.000000', NULL, 1),
(7070058, 1075388, 30490, '<td valign="top">Good image for the challenge, seems a bit soft on focus overall to me.  5 from me</td>', 'Good image for the challenge, seems a bit soft on focus overall to me.  5 from me', '2013-07-14 16:23:08.000000', NULL, 1),
