(7070260, 1075346, 57447, '<td valign="top">Neat concept.</td>', 'Neat concept.', '2013-07-14 22:53:48.000000', NULL, 1),
(7070263, 1075202, 57447, '<td valign="top">Fits challenge well.</td>', 'Fits challenge well.', '2013-07-14 22:55:11.000000', NULL, 1),
(7070271, 1075181, 57447, '<td valign="top">Fits challenge to a tee!</td>', 'Fits challenge to a tee!', '2013-07-14 22:57:28.000000', NULL, 1),
(7071590, 1075181, 147314, '<td valign="top">Great image (lovely colours and shapes, both in horizontal and vertical direction), very DMC!</td>', 'Great image (lovely colours and shapes, both in horizontal and vertical direction), very DMC!', '2013-07-16 17:33:42.000000', NULL, 1),
(7071591, 1074649, 147314, '<td valign="top">Great colours and texture.</td>', 'Great colours and texture.', '2013-07-16 17:33:59.000000', NULL, 1),
(7071592, 1075231, 147314, '<td valign="top">Great image, very clever to combine the green of the motor cycle with the red of the wall.</td>', 'Great image, very clever to combine the green of the motor cycle with the red of the wall.', '2013-07-16 17:35:04.000000', NULL, 1),
(7071595, 1075282, 147314, '<td valign="top">Very DMC, good find.</td>', 'Very DMC, good find.', '2013-07-16 17:35:44.000000', NULL, 1),
(7071596, 1074804, 147314, '<td valign="top">Nice touch, adding the boy to the already colourful background.</td>', 'Nice touch, adding the boy to the already colourful background.', '2013-07-16 17:36:40.000000', NULL, 1),
(7071598, 1075071, 147314, '<td valign="top">Nice combinations of colours.</td>', 'Nice combinations of colours.', '2013-07-16 17:37:14.000000', NULL, 1),
